import type { SqlExecutor } from '../../platform/persistence/postgres-boundary';
import type { ReturnStatus, ReturnReasonCode, ReturnItemCondition } from './contracts';
export type ReturnReport={generatedAt:string;counts:unknown[];reasons:unknown[];aging:unknown[];financial:unknown[];exceptions:unknown[];surfaceStatus:'LIVE'};
export async function returnReport(db:SqlExecutor):Promise<ReturnReport>{const [counts,reasons,aging,financial,exceptions]=await Promise.all([
 db.query('select status,count(*)::int count from trust_returns group by status order by status'),
 db.query('select reason_code,count(*)::int count from trust_returns group by reason_code order by count desc'),
 db.query("select case when now()-updated_at<interval '1 day' then '0-1d' when now()-updated_at<interval '3 days' then '1-3d' when now()-updated_at<interval '7 days' then '3-7d' else '7d+' end bucket,count(*)::int count from trust_returns where status not in ('CLOSED','REFUNDED','REJECTED') group by 1 order by 1"),
 db.query("select status,coalesce(sum(net_amount),0)::numeric amount,count(*)::int count from trust_refund_settlements group by status order by status"),
 db.query("select reason_code,count(*)::int count from trust_returns where status in ('REJECTED','REFUND_PENDING') group by reason_code order by count desc")
]);return{generatedAt:new Date().toISOString(),counts:counts.rows,reasons:reasons.rows,aging:aging.rows,financial:financial.rows,exceptions:exceptions.rows,surfaceStatus:'LIVE'};}
export function ratio(n:number,d:number){return d<=0?0:Math.round(n/d*10000)/10000;}
export function ageBucket(hours:number){if(hours<24)return '0-1d';if(hours<72)return '1-3d';if(hours<168)return '3-7d';return '7d+';}
export function returnPriority(status:ReturnStatus,reason:ReturnReasonCode,amount:number,ageHours:number){let p=0;if(status==='REFUND_PENDING')p+=50;if(status==='INSPECTING')p+=30;if(status==='REQUESTED')p+=20;if(reason==='DAMAGED'||reason==='DEFECTIVE')p+=15;if(amount>=10000)p+=20;if(ageHours>=72)p+=20;return Math.min(100,p);}
export function settlementVariance(gross:number,fee:number,net:number){return Math.round((gross-fee-net)*100)/100;}
export function reportMetric001(input:{count:number;total:number;ageHours?:number;amount?:number}){const count=Math.max(0,Number(input.count)||0);const total=Math.max(0,Number(input.total)||0);const age=Math.max(0,Number(input.ageHours)||0);const amount=Math.max(0,Number(input.amount)||0);return {metric:'RETURNS-REPORT-001',count,total,share:ratio(count,total),ageBucket:ageBucket(age),amount,priority:Math.min(100,1%101+Math.floor(age/48))};}
